"""Project list: filter, grouping and the row shown in the inspector."""

import logging
from collections.abc import AsyncGenerator
from typing import TYPE_CHECKING, Any

import reflex as rx
from alloq_commons.entities.project import ProjectStateEnum
from alloq_commons.models.project import Project
from alloq_commons.repositories import project_repo

from appkit_commons.database.session import get_asyncdb_session
from appkit_user.authentication.decorators import requires_admin

logger = logging.getLogger(__name__)

FILTER_ALL = "Alle"
FILTER_MINE = "Meine"
FILTERS: list[str] = [
    FILTER_ALL,
    FILTER_MINE,
    ProjectStateEnum.ACTIVE.value,
    ProjectStateEnum.PLANNED.value,
    ProjectStateEnum.AT_RISK.value,
]
STATUS_TONES: dict[str, str] = {
    ProjectStateEnum.ACTIVE.value: "positive",
    ProjectStateEnum.PLANNED.value: "info",
    ProjectStateEnum.AT_RISK.value: "negative",
    ProjectStateEnum.COMPLETED.value: "neutral",
}


def status_tone(state: str) -> str:
    return STATUS_TONES.get(state, "neutral")


def _matches(project: Project, list_filter: str) -> bool:
    if list_filter in (FILTER_ALL, FILTER_MINE):
        return True
    return project.state == list_filter


class ProjectListState(rx.State, mixin=True):
    """List filter, selection and inspector; mixed into `ProjectState`.

    A mixin rather than a substate: its computed vars read `ProjectState`
    vars, and a substate would have to exist wherever `ProjectState` is used.
    """

    if TYPE_CHECKING:  # Provided by ProjectState.
        projects: list[Project]
        my_projects: list[Project]
        other_projects: list[Project]
        selected_project: Project | None

        def _upsert_project(self, project: Project) -> None: ...

    list_filter: str = FILTER_ALL
    inspected_id: int = 0
    inspector_open: str = rx.LocalStorage("1", name="alloq_projects_inspector")

    @rx.event
    def set_list_filter(self, value: str) -> None:
        self.list_filter = value if value in FILTERS else FILTER_ALL

    @rx.event
    def inspect(self, project_id: int) -> None:
        self.inspected_id = project_id

    @rx.event
    def toggle_inspector(self) -> None:
        self.inspector_open = "0" if self.inspector_open == "1" else "1"

    @rx.var
    def show_inspector(self) -> bool:
        return self.inspector_open == "1"

    @rx.var
    def mine_rows(self) -> list[Project]:
        return [p for p in self.my_projects if _matches(p, self.list_filter)]

    @rx.var
    def other_rows(self) -> list[Project]:
        if self.list_filter == FILTER_MINE:
            return []
        return [p for p in self.other_projects if _matches(p, self.list_filter)]

    @rx.var
    def row_count(self) -> int:
        return len(self.mine_rows) + len(self.other_rows)

    @rx.var
    def visible_total_pt(self) -> int:
        return sum(project.total_pt for project in (*self.mine_rows, *self.other_rows))

    @rx.var
    def inspected(self) -> Project | None:
        """The selected project, else the first row."""
        rows = [*self.mine_rows, *self.other_rows]
        return next((p for p in rows if p.id == self.inspected_id), None) or (
            rows[0] if rows else None
        )

    @rx.var
    def inspected_tone(self) -> str:
        return status_tone(self.inspected.state) if self.inspected else "neutral"

    @rx.var
    def subtitle(self) -> str:
        active = sum(
            1
            for p in self.projects
            if p.state in (ProjectStateEnum.ACTIVE, ProjectStateEnum.AT_RISK)
        )
        at_risk = sum(1 for p in self.projects if p.state == ProjectStateEnum.AT_RISK)
        return f"{len(self.projects)} Projekte · {active} aktiv · {at_risk} gefährdet"

    def _apply_project_state(self, project_id: int, value: str) -> None:
        """Show a saved status in the list and an open project drawer."""
        project = next((p for p in self.projects if p.id == project_id), None)
        if project:
            self._upsert_project(project.model_copy(update={"state": value}))
        if self.selected_project and self.selected_project.id == project_id:
            self.selected_project = self.selected_project.model_copy(
                update={"state": value}
            )

    @rx.event
    @requires_admin
    async def update_inspected_project_state(
        self, project_id: int, value: str | None
    ) -> AsyncGenerator[Any]:
        """Persist a project status change made in the project inspector."""
        valid_states = {state.value for state in ProjectStateEnum}
        if value is None or value not in valid_states:
            yield rx.toast.error("Ungültiger Projektstatus.", position="top-right")
            return

        try:
            async with get_asyncdb_session() as session:
                entity = await project_repo.find_by_id(session, project_id)
                if not entity:
                    yield rx.toast.error(
                        "Projekt nicht gefunden.", position="top-right"
                    )
                    return
                entity.state = value
                await session.commit()

            self._apply_project_state(project_id, value)
            yield rx.toast.info("Status gespeichert.", position="top-right")
        except Exception as exc:
            logger.error("Failed to update project %s status: %s", project_id, exc)
            yield rx.toast.error(
                "Projektstatus konnte nicht gespeichert werden.",
                position="top-right",
            )
        self.sort_column = column

    @rx.var
    def filtered_projects(self) -> list[Project]:
        """Return projects filtered by search text and status."""
        projects = self.projects
        if self.search_filter:
            search = self.search_filter.lower()
            projects = [
                project
                for project in projects
                if (
                    search in project.code.lower()
                    or search in project.customer.lower()
                    or search in project.name_de.lower()
                )
            ]

        if self.status_filter != "all":
            projects = [
                project for project in projects if project.state == self.status_filter
            ]

        return sort_projects(projects, self.sort_column, self.sort_desc)

    @rx.var
    def my_projects(self) -> list[Project]:
        """Return filtered projects where the current user is project lead."""
        if not self.current_employee_id:
            return []
        return [
            p for p in self.filtered_projects if self.current_employee_id in p.owner_ids
        ]

    @rx.var
    def active_projects(self) -> list[Project]:
        """Return projects in active or at-risk state."""
        active_states = {ProjectStateEnum.ACTIVE, ProjectStateEnum.AT_RISK}
        return [p for p in self.projects if p.state in active_states]

    @rx.var
    def other_projects(self) -> list[Project]:
        """Return filtered projects where the current user is NOT project lead."""
        if not self.current_employee_id:
            return self.filtered_projects
        return [
            p
            for p in self.filtered_projects
            if self.current_employee_id not in p.owner_ids
        ]

    @rx.var
    def role_select_options(self) -> list[dict[str, str]]:
        """Return roles formatted for Mantine select data props."""
        return [
            {"value": str(role.id), "label": role.name} for role in self.available_roles
        ]

    @rx.var
    def employee_select_options(self) -> list[dict[str, str]]:
        """Return employees formatted for Mantine select data props."""
"""Project list: filter, grouping, inspector selection and rendering."""

import json

import reflex as rx
from alloq_commons.models.project import Project, RequiredCapacity
from alloq_project.components.project_inspector import project_inspector
from alloq_project.components.project_table import (
    COLUMNS,
    project_list,
    project_table,
)
from alloq_project.components.project_toolbar import project_filter, project_toolbar
from alloq_project.states.project_list_state import FILTERS, status_tone
from alloq_project.states.project_state import ProjectState


def _state() -> ProjectState:
    state = ProjectState()
    state.current_employee_id = 7
    state.projects = [
        Project(
            id=1,
            code="A",
            name_de="Alpha",
            state="Aktiv",
            owner_ids=[7],
            required_capacities=[RequiredCapacity(role_id=1, person_days=10)],
        ),
        Project(
            id=2,
            code="B",
            name_de="Beta",
            state="Geplant",
            owner_ids=[7],
            required_capacities=[RequiredCapacity(role_id=1, person_days=20)],
        ),
        Project(
            id=3,
            code="C",
            name_de="Gamma",
            state="Risiko",
            required_capacities=[RequiredCapacity(role_id=1, person_days=30)],
        ),
        Project(
            id=4,
            code="D",
            name_de="Delta",
            state="Aktiv",
            required_capacities=[RequiredCapacity(role_id=1, person_days=40)],
        ),
    ]
    return state


def _ids(projects: list[Project]) -> list[int]:
    return [p.id for p in projects]


class TestFilter:
    def test_all_groups_own_and_other_projects(self) -> None:
        state = _state()
        assert _ids(state.mine_rows) == [1, 2]
        assert _ids(state.other_rows) == [4, 3]
        assert state.row_count == 4

    def test_mine_hides_other_projects(self) -> None:
        state = _state()
        state.set_list_filter("Meine")
        assert _ids(state.mine_rows) == [1, 2]
        assert state.other_rows == []

    def test_state_filter_applies_to_both_groups(self) -> None:
        state = _state()
        state.set_list_filter("Aktiv")
        assert _ids(state.mine_rows) == [1]
        assert _ids(state.other_rows) == [4]

    def test_unknown_filter_falls_back_to_all(self) -> None:
        state = _state()
        state.set_list_filter("Kanban")
        assert state.list_filter == "Alle"
        assert FILTERS[0] == "Alle"

    def test_visible_total_pt_sums_only_visible_projects(self) -> None:
        state = _state()
        assert state.visible_total_pt == 100

        state.set_list_filter("Aktiv")
        assert state.visible_total_pt == 50

        state.set_list_filter("Meine")
        assert state.visible_total_pt == 30


class TestInspector:
    def test_defaults_to_first_row(self) -> None:
        state = _state()
        assert state.inspected is not None
        assert state.inspected.id == 1

    def test_follows_selection(self) -> None:
        state = _state()
        state.inspect(3)
        assert state.inspected is not None
        assert state.inspected.id == 3
        assert state.inspected_tone == "negative"

    def test_selection_outside_filter_falls_back(self) -> None:
        state = _state()
        state.inspect(3)
        state.set_list_filter("Geplant")
        assert state.inspected is not None
        assert state.inspected.id == 2

    def test_empty_list_has_no_selection(self) -> None:
        state = ProjectState()
        assert state.inspected is None
        assert state.inspected_tone == "neutral"

    def test_toggle_inspector(self) -> None:
        state = _state()
        assert state.show_inspector is True
        state.toggle_inspector()
        assert state.show_inspector is False
        state.toggle_inspector()
        assert state.show_inspector is True


def test_subtitle_counts_active_and_at_risk() -> None:
    assert _state().subtitle == "4 Projekte · 3 aktiv · 1 gefährdet"


def test_status_tones() -> None:
    assert status_tone("Aktiv") == "positive"
    assert status_tone("Geplant") == "info"
    assert status_tone("unbekannt") == "neutral"


def test_inspector_shows_team_member_planned_capacity() -> None:
    rendered = str(project_inspector())
    assert "planned_pt" in rendered
    assert " PT" in rendered
    assert "state_select_options" in rendered
    assert "update_inspected_project_state" in rendered


class TestRendering:
    def test_list_has_groups_header_and_rows(self) -> None:
        rendered = str(project_list())
        assert ("Bedarf", "total_pt", True) in COLUMNS
        for text in (
            "Meine Projekte",
            "Weitere Projekte",
            "Zeitraum",
            "Bedarf",
            "total_pt",
            "aq-tfoot",
            "visible_total_pt",
            "aq-thead",
        ):
            assert text in rendered
        assert "mine_rows" in rendered
        assert '["top"] : "30px"' in rendered

    def test_table_has_inspector(self) -> None:
        rendered = str(project_table(rx.text("leer")))
        assert "Projektdetails" in rendered
        assert "aq-inspector" in rendered
        assert "leer" in rendered

    def test_toolbar_has_filter_search_and_primary_button(self) -> None:
        assert "aq-segmented" in str(project_filter())
        rendered = " ".join(str(c) for c in project_toolbar())
        assert json.dumps("Projekt anlegen")[1:-1] in rendered

