def _matches(project: Project, list_filter: str) -> bool:
    if list_filter in (FILTER_ALL, FILTER_MINE):
        return True
    return project.state == list_filter


def _is_internal(project: Project) -> bool:
    return project.is_internal


def _is_planned(project: Project) -> bool:
    return not project.is_internal and project.state == ProjectStateEnum.PLANNED


def _is_regular(project: Project) -> bool:
    return not project.is_internal and project.state != ProjectStateEnum.PLANNED


class ProjectListState(rx.State, mixin=True):
    """List filter, selection and inspector; mixed into `ProjectState`.

    A mixin rather than a substate: its computed vars read `ProjectState`
    vars, and a substate would have to exist wherever `ProjectState` is used.
        self.list_filter = value if value in FILTERS else FILTER_ALL

    @rx.event
    def inspect(self, project_id: int) -> None:
        self.inspected_id = project_id

    @rx.event
    def toggle_inspector(self) -> None:
        self.inspector_open = "0" if self.inspector_open == "1" else "1"

    @rx.var
    def show_inspector(self) -> bool:
        return self.inspector_open == "1"

    def _rows_where(self, predicate: Callable[[Project], bool]) -> list[Project]:
        """Visible projects of any owner, respecting the "Meine" filter."""
        source = (
            self.my_projects
            if self.list_filter == FILTER_MINE
            else self.filtered_projects
        )
        return [p for p in source if predicate(p) and _matches(p, self.list_filter)]

    @rx.var
    def mine_rows(self) -> list[Project]:
        return [
            p
            for p in self.my_projects
            if _is_regular(p) and _matches(p, self.list_filter)
        ]

    @rx.var
    def other_rows(self) -> list[Project]:
        if self.list_filter == FILTER_MINE:
            return []
        return [
            p
            for p in self.other_projects
            if _is_regular(p) and _matches(p, self.list_filter)
        ]

    @rx.var
    def planned_rows(self) -> list[Project]:
        return self._rows_where(_is_planned)

    @rx.var
    def internal_rows(self) -> list[Project]:
        return self._rows_where(_is_internal)

    def _visible_rows(self) -> list[Project]:
        return [
            *self.mine_rows,
            *self.other_rows,
            *self.planned_rows,
            *self.internal_rows,
        ]

    @rx.var


class TestFilter:
    def test_all_groups_own_other_and_planned_projects(self) -> None:
        state = _state()
        assert _ids(state.mine_rows) == [1]
        assert _ids(state.other_rows) == [4, 3]
        assert _ids(state.planned_rows) == [2]
        assert state.row_count == 4

    def test_planned_group_spans_owners_in_sort_order(self) -> None:
        state = _state()
        state.projects = [
            *state.projects,
            Project(id=5, code="E", name_de="Aardvark", state="Geplant"),
        ]
        assert _ids(state.planned_rows) == [5, 2]
        assert state.row_count == 5

    def test_mine_hides_other_projects(self) -> None:
        state = _state()
        state.projects = [
            *state.projects,
            Project(id=5, code="E", name_de="Epsilon", state="Geplant"),
        ]
        state.set_list_filter("Meine")
        assert _ids(state.mine_rows) == [1]
        assert state.other_rows == []
        assert _ids(state.planned_rows) == [2]

    def test_state_filter_applies_to_all_groups(self) -> None:
        state = _state()
        state.set_list_filter("Aktiv")
        assert _ids(state.mine_rows) == [1]
        assert _ids(state.other_rows) == [4]
        assert state.planned_rows == []

    def test_planned_filter_shows_only_planned_group(self) -> None:
        state = _state()
        state.set_list_filter("Geplant")
        assert state.mine_rows == []
        assert state.other_rows == []
        assert _ids(state.planned_rows) == [2]

    def test_internal_projects_get_their_own_group(self) -> None:
        state = _state()
        state.projects = [
            *state.projects,
            Project(id=5, code="I1", name_de="Intern", is_internal=True),
            Project(id=6, code="I2", name_de="Hub", state="Aktiv", is_internal=True),
            Project(
                id=7,
                code="I3",
                name_de="Mein Intern",
                state="Aktiv",
                owner_ids=[7],
                is_internal=True,
            ),
        ]
        assert _ids(state.mine_rows) == [1]
        assert _ids(state.other_rows) == [4, 3]
        assert _ids(state.planned_rows) == [2]
        assert _ids(state.internal_rows) == [6, 5, 7]
        assert state.row_count == 7

        state.set_list_filter("Meine")
        assert _ids(state.internal_rows) == [7]

        state.set_list_filter("Aktiv")
        assert _ids(state.internal_rows) == [6, 7]

    def test_unknown_filter_falls_back_to_all(self) -> None:
        state = _state()
        state.set_list_filter("Kanban")
        assert state.list_filter == "Alle"
        assert FILTERS[0] == "Alle"

